1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import "sort"
5	
6	// Dataset is one ingestible on-chain data source with a declared schema version.
7	type Dataset struct {
8		Name          string
9		SchemaVersion int
10		Rows          int
11		Upstreams     []string
12	}
13	
14	// Lineage records where a dataset came from, so every derived table can be traced.
15	type Lineage struct {
16		Dataset  string
17		Parents  []string
18		Children []string
19	}
20	
21	// Register links a dataset into the lineage graph and rejects cycles.
22	//
23	// Re-registering an existing dataset replaces its direct upstreams with parents
24	// (de-duplicated, first occurrence wins, list order preserved) while keeping its
25	// existing direct downstreams. Reverse edges stay consistent: upstreams removed
26	// from the list drop the dataset from their children, newly added upstreams gain
27	// it at the end of their children, and retained upstreams keep exactly one entry
28	// in its original position.
29	//
30	// The whole request is validated before the graph is touched, so a rejected
31	// registration leaves every node, edge and ordering untouched. The parents slice
32	// is copied: mutating it after Register returns does not affect the graph.
33	func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
34		if dataset.Name == "" {
35			return errInvalid("dataset name is required")
36		}
37	
38		// Validate up front, walking the request in input order so the first problem
39		// encountered is the one reported. No graph mutation happens in this loop.
40		upstreams := make([]string, 0, len(parents))
41		known := map[string]bool{}
42		// All cycle checks in this one request share a single memoized walk over the
43		// graph as it stands now: probe records whether each visited node can reach
44		// dataset.Name through existing parent edges. Candidate upstreams that come
45		// from the same source or merge repeatedly (diamonds) then traverse the
46		// shared lineage once instead of re-walking it per candidate. The recorded
47		// conclusion is a property of the current graph, so it is never reused
48		// across registrations.
49		probe := newAncestorProbe(graph, dataset.Name)
50		for _, parent := range parents {
51			if parent == dataset.Name {
52				return errInvalid("dataset " + dataset.Name + " cannot be its own parent")
53			}
54			if _, ok := graph[parent]; !ok {
55				return errInvalid("unknown parent " + parent)
56			}
57			// A new edge dataset -> parent closes a cycle exactly when parent can
58			// already reach dataset through existing parent edges. This covers
59			// transitive paths of any depth, not only direct mutual references;
60			// shared ancestors and diamond merges read as the benign merges they are
61			// unless a branch genuinely leads back to dataset.
62			if probe.canReach(parent) {
63				return errInvalid("cycle through " + parent + " for dataset " + dataset.Name)
64			}
65			if !known[parent] {
66				known[parent] = true
67				upstreams = append(upstreams, parent)
68			}
69		}
70	
71		entry, existed := graph[dataset.Name]
72		if !existed {
73			entry = &Lineage{Dataset: dataset.Name}
74		}
75	
76		// Remove reverse edges from upstreams the dataset no longer declares.
77		for _, old := range entry.Parents {
78			if known[old] {
79				continue
80			}
81			if p, ok := graph[old]; ok {
82				p.Children = removeChild(p.Children, dataset.Name)
83			}
84		}
85	
86		// Mirror every declared upstream exactly once. An existing edge keeps its
87		// position; a missing edge is appended after the current children.
88		for _, parent := range upstreams {
89			graph[parent].Children = addChildOnce(graph[parent].Children, dataset.Name)
90		}
91	
92		entry.Parents = upstreams
93		if !existed {
94			graph[dataset.Name] = entry
95		}
96		return nil
97	}
98	
99	// Rename changes the registered name of the dataset oldName to newName while
100	// keeping the dataset's exact position in the lineage graph: the node keeps
101	// its own direct upstream and downstream lists untouched, and every neighbor
102	// that referenced oldName now references newName in the same list position.
103	// No edge is added, removed, merged or reordered, and the total number of
104	// datasets in the graph is unchanged. Roots, leaves and intermediate datasets
105	// can all be renamed.
106	//
107	// The request is validated before the graph is touched, so a rejected rename
108	// leaves every node, edge and list order untouched. Names match by exact
109	// registered value (case-sensitive). An empty old or new name is rejected as
110	// a missing name; an oldName absent from the graph is rejected with an error
111	// naming it; a newName already registered to a different dataset is rejected
112	// with an error naming it. Renaming a dataset to its own current name is a
113	// successful no-op.
114	func Rename(graph map[string]*Lineage, oldName, newName string) error {
115		if oldName == "" {
116			return errInvalid("dataset name is required")
117		}
118		if newName == "" {
119			return errInvalid("new dataset name is required")
120		}
121		entry, ok := graph[oldName]
122		if !ok {
123			return errInvalid("dataset not found: " + oldName)
124		}
125		if oldName == newName {
126			return nil
127		}
128		if _, taken := graph[newName]; taken {
129			return errInvalid("dataset name already in use: " + newName)
130		}
131	
132		delete(graph, oldName)
133		entry.Dataset = newName
134		graph[newName] = entry
135	
136		// Rewire the reverse references in place: the renamed node keeps its slot
137		// in every neighbor's list, so each neighbor's ordering is preserved.
138		for _, parent := range entry.Parents {
139			children := graph[parent].Children
140			for i, child := range children {
141				if child == oldName {
142					children[i] = newName
143				}
144			}
145		}
146		for _, child := range entry.Children {
147			parents := graph[child].Parents
148			for i, parent := range parents {
149				if parent == oldName {
150					parents[i] = newName
151				}
152			}
153		}
154		return nil
155	}
156	
157	// ancestorProbe answers "can node reach target by following parent edges?" for
158	// many starting nodes against one fixed, read-only snapshot of the graph, i.e.
159	// whether target is among each node's direct or transitive upstreams. Each node
160	// in the shared ancestry is resolved at most once, so candidate parents that
161	// descend from a common source or merge along the way reuse the same findings
162	// instead of each paying for a complete traversal.
163	type ancestorProbe struct {
164		graph  map[string]*Lineage
165		target string
166		// resolved caches the conclusion for every fully explored node; visiting
167		// marks nodes mid-resolution. Register never accepts cycles, but visiting
168		// doubles as cycle protection regardless.
169		resolved map[string]bool
170		visiting map[string]bool
171	}
172	
173	func newAncestorProbe(graph map[string]*Lineage, target string) *ancestorProbe {
174		return &ancestorProbe{
175			graph:    graph,
176			target:   target,
177			resolved: map[string]bool{},
178			visiting: map[string]bool{},
179		}
180	}
181	
182	func (p *ancestorProbe) canReach(node string) bool {
183		if node == p.target {
184			return true
185		}
186		if hit, ok := p.resolved[node]; ok {
187			return hit
188		}
189		if p.visiting[node] {
190			return false
191		}
192		p.visiting[node] = true
193	
194		found := false
195		if entry, ok := p.graph[node]; ok {
196			for _, parent := range entry.Parents {
197				if p.canReach(parent) {
198					found = true
199					break
200				}
201			}
202		}
203		delete(p.visiting, node)
204		p.resolved[node] = found
205		return found
206	}
207	
208	// removeChild drops every occurrence of child from children, preserving the
209	// relative order of the remaining entries.
210	func removeChild(children []string, child string) []string {
211		out := children[:0]
212		for _, c := range children {
213			if c != child {
214				out = append(out, c)
215			}
216		}
217		return out
218	}
219	
220	// addChildOnce ensures child appears exactly once in children. An existing entry
221	// keeps its position (duplicate later entries are dropped); otherwise child is
222	// appended at the end.
223	func addChildOnce(children []string, child string) []string {
224		out := children[:0]
225		present := false
226		for _, c := range children {
227			if c == child {
228				if present {
229					continue
230				}
231				present = true
232			}
233			out = append(out, c)
234		}
235		if !present {
236			out = append(out, child)
237		}
238		return out
239	}
240	
241	// Impact names one dataset directly or indirectly downstream of an impact
242	// query's origin. Distance is the number of lineage edges on the shortest path
243	// from the origin to this dataset (a direct downstream has distance 1), and
244	// Path is that shortest path written from the origin to the dataset, one name
245	// per hop.
246	type Impact struct {
247		Dataset  string
248		Distance int
249		Path     []string
250	}
251	
252	// Impacts returns every dataset directly or indirectly downstream of origin,
253	// i.e. every dataset reachable from origin by following child edges. The origin
254	// itself is never listed, and datasets with no such connection never appear.
255	//
256	// Distance, the tie-broken explanation path, result ordering, read-only graph
257	// access and error handling all follow the single shared lineage-query rule
258	// set implemented by traceLineage; only the direction is specific to Impacts:
259	// child edges outward, with paths written from the origin. An empty origin is
260	// rejected as a missing name; an origin absent from the graph (including an
261	// empty or nil graph) is rejected with an error naming it and no partial
262	// results.
263	func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
264		hits, err := traceLineage(graph, origin, dirDownstream)
265		if err != nil {
266			return nil, err
267		}
268		impacts := make([]Impact, len(hits))
269		for i, hit := range hits {
270			impacts[i] = Impact{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
271		}
272		return impacts, nil
273	}
274	
275	// Upstream names one dataset directly or indirectly upstream of a provenance
276	// query's target. Distance is the number of lineage edges on the shortest path
277	// from this upstream to the target (a direct upstream has distance 1), and
278	// Path is that shortest path written along the actual derivation direction,
279	// from this upstream to the queried dataset, one name per hop.
280	type Upstream struct {
281		Dataset  string
282		Distance int
283		Path     []string
284	}
285	
286	// Upstreams returns every dataset directly or indirectly upstream of target,
287	// i.e. every dataset reachable from target by following parent edges. The
288	// target itself is never listed, its downstreams never appear, and datasets
289	// with no such connection never appear.
290	//
291	// Distance, the tie-broken explanation path, result ordering, read-only graph
292	// access and error handling all follow the single shared lineage-query rule
293	// set implemented by traceLineage; only the direction is specific to
294	// Upstreams: parent edges inward, with paths written from each source toward
295	// the target. An empty target is rejected as a missing name; a target absent
296	// from the graph (including an empty or nil graph) is rejected with an error
297	// naming it and no partial results.
298	func Upstreams(graph map[string]*Lineage, target string) ([]Upstream, error) {
299		hits, err := traceLineage(graph, target, dirUpstream)
300		if err != nil {
301			return nil, err
302		}
303		upstreams := make([]Upstream, len(hits))
304		for i, hit := range hits {
305			upstreams[i] = Upstream{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
306		}
307		return upstreams, nil
308	}
309	
310	// queryDirection carries the only way the two lineage queries differ: which
311	// edges to walk and from which end an explanation path is written.
312	type queryDirection int
313	
314	const (
315		// dirDownstream follows child edges away from the query's origin and grows
316		// explanation paths at the far end (origin -> ... -> dataset).
317		dirDownstream queryDirection = iota
318		// dirUpstream follows parent edges away from the query's target and grows
319		// explanation paths at the near end (source -> ... -> target).
320		dirUpstream
321	)
322	
323	// neighbors lists the datasets one edge beyond node in the query direction.
324	func (d queryDirection) neighbors(node *Lineage) []string {
325		if d == dirDownstream {
326			return node.Children
327		}
328		return node.Parents
329	}
330	
331	// extendPath grows a committed shortest path by one hop, placing the new hop
332	// where the explanation direction requires: a downstream hop is appended
333	// (origin -> node -> hop), an upstream hop is prepended (hop -> node ->
334	// target). The result always gets a fresh backing array, so candidates never
335	// alias each other, committed paths, or slices stored in the graph.
336	func (d queryDirection) extendPath(path []string, hop string) []string {
337		extended := make([]string, len(path)+1)
338		if d == dirDownstream {
339			copy(extended, path)
340			extended[len(extended)-1] = hop
341			return extended
342		}
343		extended[0] = hop
344		copy(extended[1:], path)
345		return extended
346	}
347	
348	// lineageHit is one direction-neutral query result: a reached dataset besides
349	// the query's own node, its shortest edge distance, and the lexicographically
350	// smallest shortest explanation path held in an independent slice.
351	type lineageHit struct {
352		name     string
353		distance int
354		path     []string
355	}
356	
357	// traceLineage runs the one query rule set shared by Impacts and Upstreams and
358	// returns every dataset reachable from start besides start itself.
359	//
360	// The traversal is a BFS that commits a whole distance level at once, so a node
361	// reached through several branches within the same level keeps exactly one
362	// candidate before the level commits. The rules shared by both directions are:
363	//
364	//   - Distance is the minimum number of lineage edges; a node committed on an
365	//     earlier level can never be re-explained at a longer one (Register
366	//     rejects cycles, so equal-length rediscoveries only happen inside one
367	//     level's candidate map).
368	//   - Each dataset appears at most once, however many branches merge into it.
369	//   - Among equal-length shortest paths, the lexicographically smallest full
370	//     path wins: names are compared one by one from the path's beginning in Go
371	//     string order. Downstream paths begin at the query origin and upstream
372	//     paths at the source, so candidates for one upstream share their first
373	//     hop and compare directly against the committed tails.
374	//   - Hits are ordered by distance ascending and then by dataset name, never
375	//     by registration order or the stored parent/child list order.
376	//
377	// Explanation paths are written in the query direction (see extendPath). The
378	// graph is read only and every returned path is an independent copy. An empty
379	// start is rejected as a missing name; an unregistered start (also against an
380	// empty or nil graph) is rejected with an error naming it, with nil results;
381	// a registered start that reaches nothing returns a non-nil empty slice.
382	func traceLineage(graph map[string]*Lineage, start string, direction queryDirection) ([]lineageHit, error) {
383		if start == "" {
384			return nil, errInvalid("dataset name is required")
385		}
386		if _, ok := graph[start]; !ok {
387			return nil, errInvalid("dataset not found: " + start)
388		}
389	
390		distance := map[string]int{start: 0}
391		best := map[string][]string{start: {start}}
392		frontier := []string{start}
393		for level := 0; len(frontier) > 0; level++ {
394			nextDistance := level + 1
395			candidates := map[string][]string{}
396			var next []string
397			for _, node := range frontier {
398				for _, hop := range direction.neighbors(graph[node]) {
399					if _, seen := distance[hop]; seen {
400						continue // reached on an earlier, strictly shorter level
401					}
402					candidate := direction.extendPath(best[node], hop)
403					if current, ok := candidates[hop]; !ok || lessPath(candidate, current) {
404						if !ok {
405							next = append(next, hop)
406						}
407						candidates[hop] = candidate
408					}
409				}
410			}
411			for _, hop := range next {
412				distance[hop] = nextDistance
413				best[hop] = candidates[hop]
414			}
415			frontier = next
416		}
417	
418		hits := make([]lineageHit, 0, len(distance)-1)
419		for name, d := range distance {
420			if name == start {
421				continue
422			}
423			hits = append(hits, lineageHit{
424				name:     name,
425				distance: d,
426				path:     append([]string(nil), best[name]...),
427			})
428		}
429		sort.Slice(hits, func(i, j int) bool {
430			if hits[i].distance != hits[j].distance {
431				return hits[i].distance < hits[j].distance
432			}
433			return hits[i].name < hits[j].name
434		})
435		return hits, nil
436	}
437	
438	// lessPath reports whether path a sorts before path b as a name sequence:
439	// names are compared with Go string order from the start, and an equal prefix
440	// makes the shorter path smaller.
441	func lessPath(a, b []string) bool {
442		for i := 0; i < len(a) && i < len(b); i++ {
443			if a[i] != b[i] {
444				return a[i] < b[i]
445			}
446		}
447		return len(a) < len(b)
448	}
449	
450	// Roots lists datasets with no parents, in stable order.
451	func Roots(graph map[string]*Lineage) []string {
452		var roots []string
453		for name, entry := range graph {
454			if len(entry.Parents) == 0 {
455				roots = append(roots, name)
456			}
457		}
458		sort.Strings(roots)
459		return roots
460	}
461	
462	type errInvalid string
463	
464	func (e errInvalid) Error() string { return string(e) }
465

